const configText = $input.item.json.stdout || '{}';
const config = JSON.parse(configText);

const now = new Date();
const timestamp = now.toISOString().replace(/[:.]/g, '-').slice(0, 19);

return [{
  json: {
    jobTitles: config.job_titles || ['Engineering Manager'],
    location: config.location || 'London, UK',
    timeRange: config.time_range || '48h',
    excludeKeywords: config.exclude_keywords || [],
    mustHaveKeywords: config.must_have || [],
    minScore: config.min_score || 7,
    maxJobs: config.max_jobs_per_title || 20,
    ollamaModel: config.ollama_model || 'qwen2.5:latest',
    ollamaUrl: config.ollama_url || 'http://host.docker.internal:11434',
    runTimestamp: timestamp,
    outputFileMatches: `/data/n8n_linkedin/output/matches_${timestamp}.json`,
    outputFileRejected: `/data/n8n_linkedin/output/rejected_${timestamp}.json`,
    metadata: {
      source: 'LinkedIn (via Python scraper)',
      aiProvider: 'Ollama (local)',
      aiModel: config.ollama_model || 'qwen2.5:latest',
      candidateName: 'Joao Lourenco',
      runDate: now.toISOString(),
      configVersion: '3.0'
    }
  }
}];

const jobsText = $input.item.json.stdout || '[]';
let jobs = [];

try {
  jobs = JSON.parse(jobsText);
} catch(e) {
  console.log('JSON parse error:', e.message);
  return [];
}

if (!Array.isArray(jobs) || jobs.length === 0) {
  return [];
}

const config = $('Parse Config').item.json;
const searchTitle = $('Loop Job Titles').item.json.jobTitles;

console.log(`Processing ${jobs.length} jobs for: ${searchTitle}`);

return jobs.map((job, idx) => ({
  json: {
    job: {
      title: job.title || 'Unknown Title',
      company: job.company || 'Unknown Company',
      location: job.location || '',
      job_link: job.job_link || '',
      posted_date: job.posted_date || '',
      description: job.description || ''
    },
    searchTitle: searchTitle,
    config: config,
    _index: idx
  }
}));

const item = $input.item.json;
const job = item.job;
const config = item.config;

// Skip jobs without proper data
if (!job || !job.title || job.title === 'Unknown Title') {
  console.log('Skipping job with missing title');
  return [];
}

if (!job.description || job.description.length < 50) {
  console.log(`Skipping ${job.title} - no description`);
  return [];
}

// Clean description for prompt
const cleanDesc = job.description
  .substring(0, 2000)
  .replace(/[\x00-\x1F\x7F]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

// Build the Ollama request body as proper object
const systemPrompt = `You are a job matching assistant. Analyze job postings and return JSON assessments.

CANDIDATE PROFILE:
Name: Joao Lourenco
Role: Engineering Manager
Location: London, UK
Experience: 14+ years software quality, 8+ years leading teams
Team Size: Managed 16 people including 2 Engineering Managers
Scaling: Grew teams from 4 to 16 engineers with 100% UK retention
Domains: Safety-critical (automotive, aerospace, defence), static analysis
Compliance: ISO 9001, ISO 27001, DO-178B
Technical: Test automation, CI/CD, Python, TypeScript, Jenkins, AWS
Achievements: Reduced 4-month testing to 2-day automated, 90% defect reduction

REJECT IF:
- Hands-on IC coding role (not management)
- Hardware/embedded/electrical engineering
- Mechanical/civil/construction
- Junior or mid-level positions
- C-suite requiring 20+ years
- Non-software industries

SCORING:
9-10: Perfect match (EM, safety-critical, team scaling)
7-8: Strong match (EM software, good seniority)
5-6: Partial match (some alignment)
1-4: Poor match

Return ONLY valid JSON, no markdown.`;

const userPrompt = `Analyze this job:

Title: ${job.title}
Company: ${job.company}
Location: ${job.location}

Description:
${cleanDesc}

---
Return JSON with these fields:
{
  "relevant": true/false,
  "rejection_reason": null or string,
  "score": 1-10,
  "company_size": string,
  "company_industry": string,
  "company_about": string (1-2 sentences about the company),
  "role_summary": string (what THIS JOB involves, not the candidate),
  "match_reasons": [array of 2-4 reasons],
  "concerns": [array of any concerns],
  "seniority_level": string
}`;

const ollamaPayload = {
  model: config.ollamaModel,
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userPrompt }
  ],
  stream: false,
  options: { temperature: 0.3 }
};

return [{
  json: {
    job: job,
    searchTitle: item.searchTitle,
    config: config,
    ollamaPayload: ollamaPayload
  }
}];

const item = $input.item.json;
const prevData = $('Build Analyze Request').item.json;

// Extract response text
let responseText = '';
try {
  if (item.message && item.message.content) {
    responseText = item.message.content;
  } else if (item.response) {
    responseText = item.response;
  } else {
    responseText = JSON.stringify(item);
  }
} catch(e) {
  console.log('Error extracting response:', e.message);
}

// Clean markdown
responseText = responseText
  .replace(/```json\n?/gi, '')
  .replace(/```\n?/g, '')
  .trim();

// Default analysis
let analysis = {
  relevant: false,
  rejection_reason: 'Failed to parse AI response',
  score: 0,
  company_size: 'Unknown',
  company_industry: 'Unknown',
  company_about: '',
  role_summary: '',
  match_reasons: [],
  concerns: ['AI parsing failed'],
  seniority_level: 'Unknown'
};

try {
  const jsonMatch = responseText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    analysis = JSON.parse(jsonMatch[0]);
  }
} catch(e) {
  console.log('JSON parse error:', e.message);
  console.log('Raw:', responseText.substring(0, 500));
}

analysis.score = parseInt(analysis.score) || 0;

return [{
  json: {
    job: prevData.job,
    analysis: analysis,
    searchTitle: prevData.searchTitle,
    config: prevData.config
  }
}];

const data = $input.item.json;
const job = data.job;
const analysis = data.analysis;
const config = data.config;

const systemPrompt = 'Write a professional cover letter. Be concise (300-400 words). No placeholder brackets. Ready to send.';

const userPrompt = `Write a cover letter for Joao Lourenco applying to:

Position: ${job.title}
Company: ${job.company}
Location: ${job.location}

Role Summary: ${analysis.role_summary}

Why this matches:
${(analysis.match_reasons || []).join('\n')}

Candidate highlights:
- Engineering Manager, 14+ years experience
- Scaled teams 4 to 16 engineers (manager of managers)
- 100% UK team retention
- Safety-critical: automotive, aerospace, defence
- Transformed 4-month testing to 2-day automated
- 90% defect reduction
- ISO 9001/27001 compliance

Address to 'Hiring Manager', sign as 'Joao Lourenco'.`;

const ollamaPayload = {
  model: config.ollamaModel,
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userPrompt }
  ],
  stream: false,
  options: { temperature: 0.7 }
};

return [{
  json: {
    job: job,
    analysis: analysis,
    searchTitle: data.searchTitle,
    config: config,
    ollamaPayload: ollamaPayload
  }
}];

const ollamaResponse = $input.item.json;
const prevData = $('Build Cover Request').item.json;

let coverLetter = '';
try {
  if (ollamaResponse.message && ollamaResponse.message.content) {
    coverLetter = ollamaResponse.message.content;
  } else if (ollamaResponse.response) {
    coverLetter = ollamaResponse.response;
  }
} catch(e) {
  coverLetter = 'Error generating cover letter';
}

const matchRecord = {
  job: prevData.job,
  analysis: prevData.analysis,
  cover_letter: coverLetter.trim(),
  metadata: {
    ...prevData.config.metadata,
    searchTitle: prevData.searchTitle,
    processedAt: new Date().toISOString(),
    status: 'matched'
  }
};

return [{
  json: {
    record: matchRecord,
    outputFile: prevData.config.outputFileMatches,
    config: prevData.config
  }
}];

const record = $input.item.json.record;
const outputFile = $input.item.json.outputFile;
const config = $input.item.json.config;

const recordJson = JSON.stringify(record);
const recordBase64 = Buffer.from(recordJson).toString('base64');

return [{
  json: {
    recordBase64: recordBase64,
    outputFile: outputFile,
    config: config
  }
}];

const data = $input.item.json;

const rejectedRecord = {
  job: data.job,
  analysis: {
    relevant: data.analysis.relevant,
    rejection_reason: data.analysis.rejection_reason || `Score ${data.analysis.score} below minimum ${data.config.minScore}`,
    score: data.analysis.score,
    company_size: data.analysis.company_size,
    company_industry: data.analysis.company_industry,
    seniority_level: data.analysis.seniority_level
  },
  metadata: {
    ...data.config.metadata,
    searchTitle: data.searchTitle,
    processedAt: new Date().toISOString(),
    status: 'rejected'
  }
};

return [{
  json: {
    record: rejectedRecord,
    outputFile: data.config.outputFileRejected,
    config: data.config
  }
}];

const record = $input.item.json.record;
const outputFile = $input.item.json.outputFile;
const config = $input.item.json.config;

const recordJson = JSON.stringify(record);
const recordBase64 = Buffer.from(recordJson).toString('base64');

return [{
  json: {
    recordBase64: recordBase64,
    outputFile: outputFile,
    config: config
  }
}];
